/**
 * Compatibility artifact builders owned by the reviewed Supabase provider.
 * The legacy React adapter delegates here so existing generated bytes remain
 * stable while Supabase-specific artifact ownership no longer lives in the
 * target adapter.
 */

export const SUPABASE_JS_VERSION = '^2.100.0'

/**
 * Legacy executable workflow bundle paths. Keeping these beside the reviewed
 * byte builders gives the React adapter an explicit ownership contract instead
 * of asking build/deploy callers to infer execution semantics from prefixes.
 */
export const LEGACY_SUPABASE_SERVER_WORKFLOW_ARTIFACT_PATHS = Object.freeze([
  'supabase/functions/openpencil-runtime/index.ts',
  '.env.server.example',
  'openpencil-server.manifest.json',
  'SERVER_DEPLOYMENT.md'
] as const)

export interface LegacySupabaseClientConfig {
  readonly url: string
  /** Serialized compatibility field; accepts a publishable key or legacy anon JWT. */
  readonly anonKey: string
  readonly schema?: string
}

export function buildLegacySupabaseClientRuntime(config: LegacySupabaseClientConfig): string {
  const url = JSON.stringify(config.url)
  const anonKey = JSON.stringify(config.anonKey)
  const schema = JSON.stringify(config.schema?.trim() || 'public')
  return `// Auto-generated by OpenPencil compiler (Phase 3 §2). Do not edit by hand.
import { createClient, type Session } from '@supabase/supabase-js'

import { setDocState, useDocState } from './_lowcode_state'

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL ?? ${url}
const SUPABASE_PUBLISHABLE_KEY_INPUT = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY
const SUPABASE_LEGACY_ANON_KEY_INPUT = import.meta.env.VITE_SUPABASE_ANON_KEY
const SUPABASE_SCHEMA = import.meta.env.VITE_SUPABASE_SCHEMA ?? ${schema}

function legacySupabaseRole(key: string): unknown {
  const parts = key.split('.')
  if (parts.length !== 3) return null
  try {
    const base64 = parts[1].replaceAll('-', '+').replaceAll('_', '/')
    const binary = atob(base64 + '='.repeat((4 - (base64.length % 4)) % 4))
    const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0))
    const payload: unknown = JSON.parse(new TextDecoder().decode(bytes))
    return payload !== null && typeof payload === 'object' && !Array.isArray(payload)
      ? (payload as Record<string, unknown>).role
      : null
  } catch {
    return null
  }
}

function assertSupabasePublicKey(value: string): string {
  const key = value.trim()
  if (
    !key ||
    /^sb_secret_/i.test(key) ||
    /^sbp_/i.test(key) ||
    legacySupabaseRole(key) === 'service_role'
  ) {
    throw new Error('Supabase client configuration contains an invalid or elevated key')
  }
  return key
}

function resolveSupabasePublicKey(
  publishableKey: string | undefined,
  legacyAnonKey: string | undefined,
  fallback: string
): string {
  const publishable =
    publishableKey === undefined ? undefined : assertSupabasePublicKey(publishableKey)
  const legacy = legacyAnonKey === undefined ? undefined : assertSupabasePublicKey(legacyAnonKey)
  if (publishable && legacy && publishable !== legacy) {
    throw new Error('Supabase client configuration contains conflicting public keys')
  }
  return publishable ?? legacy ?? assertSupabasePublicKey(fallback)
}

const SUPABASE_PUBLISHABLE_KEY = resolveSupabasePublicKey(
  SUPABASE_PUBLISHABLE_KEY_INPUT,
  SUPABASE_LEGACY_ANON_KEY_INPUT,
  ${anonKey}
)

let _client: ReturnType<typeof createClient> | null = null
export function getSupabaseClient() {
  if (!_client) {
    _client = createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
      db: { schema: SUPABASE_SCHEMA }
    })
  }
  return _client
}

const supabase = getSupabaseClient()

function toCurrentUser(session: Session | null): Record<string, unknown> {
  return {
    id: session?.user.id ?? null,
    email: session?.user.email ?? null,
    signedIn: !!session
  }
}

void supabase.auth.getSession().then(({ data: { session } }) => {
  setDocState('$currentUser', toCurrentUser(session))
})
supabase.auth.onAuthStateChange((_event, session) => {
  setDocState('$currentUser', toCurrentUser(session))
})

export function useSupabaseAuth() {
  const user = useDocState('$currentUser')
  return {
    user,
    signIn: (email: string, password: string) =>
      supabase.auth.signInWithPassword({ email, password }),
    signOut: () => supabase.auth.signOut()
  }
}
`
}

export function buildLegacySupabaseViteEnvironmentTypes(): string {
  return `/// <reference types="vite/client" />\n`
}

export function buildLegacySupabaseEnvironmentExample(config: LegacySupabaseClientConfig): string {
  return `# Supabase connection for the deployed app.
# Copy this file to .env and edit per environment (preview / staging / prod).
# Unset values fall back to the design-time project baked into the build.
VITE_SUPABASE_URL=${config.url}
VITE_SUPABASE_PUBLISHABLE_KEY=${config.anonKey}
VITE_SUPABASE_SCHEMA=${config.schema?.trim() || 'public'}
`
}

export interface LegacySupabaseServerWorkflowDescriptor {
  readonly id: string
  readonly name: string
  readonly params: readonly string[]
}

export interface LegacySupabaseServerArtifactSet {
  readonly edgeFunction: string
  readonly envExample: string
  readonly manifest: string
  readonly readme: string
}

export interface AssembleLegacySupabaseServerArtifactsInput {
  readonly edgeFunction: string
  readonly workflows: readonly LegacySupabaseServerWorkflowDescriptor[]
  readonly environmentNames: readonly string[]
}

/** Preserve the legacy artifact bytes while centralizing Supabase ownership. */
export function assembleLegacySupabaseServerArtifacts(
  input: AssembleLegacySupabaseServerArtifactsInput
): LegacySupabaseServerArtifactSet {
  const environmentNames = [...input.environmentNames].sort((left, right) =>
    left.localeCompare(right, 'en')
  )
  return {
    edgeFunction: input.edgeFunction,
    envExample:
      [
        'SUPABASE_URL=',
        '# Hosted Edge Functions inject this JSON dictionary automatically.',
        '# SUPABASE_PUBLISHABLE_KEYS={"default":"sb_publishable_..."}',
        '# Legacy fallback only; leave SUPABASE_PUBLISHABLE_KEYS unset when using it.',
        '# SUPABASE_ANON_KEY=',
        ...environmentNames.map((name) => `${name}=`)
      ].join('\n') + '\n',
    manifest:
      JSON.stringify(
        {
          version: 1,
          function: 'openpencil-runtime',
          deploy: 'manual',
          auth: 'supabase-user',
          workflows: input.workflows.map((workflow) => ({
            id: workflow.id,
            name: workflow.name,
            method: 'POST',
            params: workflow.params
          })),
          environment: ['SUPABASE_URL', 'SUPABASE_PUBLISHABLE_KEYS', ...environmentNames],
          legacyEnvironmentFallbacks: {
            SUPABASE_PUBLISHABLE_KEYS: 'SUPABASE_ANON_KEY'
          }
        },
        null,
        2
      ) + '\n',
    readme: buildLegacySupabaseServerReadme(environmentNames)
  }
}

function buildLegacySupabaseServerReadme(environmentNames: readonly string[]): string {
  const custom = environmentNames.length > 0 ? ` plus ${environmentNames.join(', ')}` : ''
  return `# OpenPencil server workflows

This directory is generated deployment source. It is intentionally excluded from the static web bundle and is never deployed automatically.

1. Review \`supabase/functions/openpencil-runtime/index.ts\`.
2. Use the hosted \`SUPABASE_URL\` and \`SUPABASE_PUBLISHABLE_KEYS\` values${custom}. The generated function selects the \`default\` publishable key from that JSON dictionary. For an older project or local runner, leave \`SUPABASE_PUBLISHABLE_KEYS\` unset and configure \`SUPABASE_ANON_KEY\` instead. Never commit populated values.
3. From this directory, run \`supabase functions deploy openpencil-runtime\`.

The function accepts authenticated POST requests only and uses the caller's bearer token for Row Level Security. It never uses an \`sb_secret_*\`, \`sbp_*\` Management PAT, or legacy \`service_role\` credential.
`
}
